// Why Code: base64 from the page → an audio file, named for what the phone recorded (Android: webm, iPhone: mp4).
const b = $('Photo to file').item.json.body;
const mime = String(b.audio_mime || 'audio/webm').split(';')[0];
const ext = { 'audio/webm': 'webm', 'audio/mp4': 'm4a', 'audio/aac': 'aac', 'audio/ogg': 'ogg', 'audio/mpeg': 'mp3', 'audio/wav': 'wav' }[mime] || 'webm';
return { json: { capture_id: b.capture_id }, binary: { data: { data: b.audio_b64, mimeType: mime, fileName: b.capture_id + '.' + ext, fileExtension: ext } } };

