// Check the area shape: generated from n8n/mobilise/logic.mjs validateZone. Edit there, then rebuild.
const __fn = function validateZone(input) {
  const b = input.body || {}
  const errors = []
  const areas = Array.isArray(input.areas) ? input.areas : []
  const sh = b.shape || {}
  const okPt = (p) => Array.isArray(p) && p.length === 2 && Math.abs(p[0]) <= 90 && Math.abs(p[1]) <= 180
  if (!/^[A-Z]{2,3}$/.test(String(b.area || ''))) errors.push('area must be an area code like LC')
  else if (areas.length && !areas.includes(b.area)) errors.push('area ' + b.area + ' is not on this site\'s checklist')
  let shape = null
  if (sh.circle) {
    const c = sh.circle
    if (!(Math.abs(c.lat) <= 90 && Math.abs(c.lng) <= 180)) errors.push('circle centre is not a valid point')
    if (!(c.radius_m >= 5 && c.radius_m <= 150)) errors.push('radius must be 5 to 150 m')
    if (!(c.accuracy_m > 0 && c.accuracy_m <= 30)) errors.push('GPS was too weak to mark the area (need ±30 m or better)')
    shape = { circle: { lat: Number(c.lat), lng: Number(c.lng), radius_m: Math.round(c.radius_m) } }
  } else if (Array.isArray(sh.polygon)) {
    const p = sh.polygon
    if (p.length < 3 || p.length > 30 || !p.every(okPt)) errors.push('outline needs 3 to 30 valid corners')
    else {
      const R = 6371000
      const lat0 = p[0][0] * Math.PI / 180
      const xy = p.map((q) => [q[1] * Math.PI / 180 * R * Math.cos(lat0), q[0] * Math.PI / 180 * R])
      let a = 0
      for (let i = 0, j = xy.length - 1; i < xy.length; j = i++) a += xy[j][0] * xy[i][1] - xy[i][0] * xy[j][1]
      const area = Math.abs(a / 2)
      if (area < 20) errors.push('outline is too small (under 20 m²): walk the real corners')
      if (area > 200000) errors.push('outline is larger than 20 hectares')
    }
    if (!(sh.accuracy_m > 0 && sh.accuracy_m <= 30)) errors.push('GPS was too weak at one of the corners (need ±30 m or better)')
    shape = { polygon: p.map((q) => [Number(q[0]), Number(q[1])]) }
  } else errors.push('shape must be a circle or a polygon')
  const name = String(b.name || '').trim().slice(0, 60) || String(b.area || '')
  return { ...input, valid: errors.length === 0, errors, zone: { area: b.area, name, shape } }
};
const item = $input.item;
let input = { ...item.json };
input.body = $('Check walk link ').item.json.body;
const out = __fn(input);
return item.binary ? { json: out, binary: item.binary } : { json: out };

// Why Code: verifies the sticker's signature (HMAC) with the walk secret.
const crypto = require('crypto');
const item = $input.item;
const code = String((item.json.body || {}).code || '');
const parts = code.split('.');
const want = crypto.createHmac('sha256', $env.VERA_WALK_SECRET || '').update('spot.' + parts.slice(0, 3).join('.')).digest('base64url').slice(0, 22);
const sig = parts[3] || '';
const ok = parts.length === 4 && /^\d+$/.test(parts[0]) && /^[A-Z]{2,3}$/.test(parts[1]) && /^\d{1,2}$/.test(parts[2]) && sig.length === want.length && crypto.timingSafeEqual(Buffer.from(sig), Buffer.from(want));
return { json: { ...item.json, spot_ok: ok, spot: ok ? { mobilisation_id: Number(parts[0]), area: parts[1], sticker: Number(parts[2]) } : null } };

parameters.query:
insert into spot_checks (walk_id, area, sticker, ts, gps)
select w.id, $2, $3, coalesce(nullif($4, '')::timestamptz, now()), $5::jsonb from walks w where w.id = $1 and w.mobilisation_id = $6
on conflict do nothing returning area;

parameters.jsCode:
// Why Code: signs one code per sticker (HMAC with the walk secret).
const crypto = require('crypto');
const item = $input.item;
const per = Math.max(1, Math.min(20, Number(($('Check walk link ').item.json.body || {}).per_area) || 4));
const sign = (s) => crypto.createHmac('sha256', $env.VERA_WALK_SECRET || '').update('spot.' + s).digest('base64url').slice(0, 22);
const stickers = [];
for (const a of item.json.areas || []) for (let n = 1; n <= per; n++) { const s = item.json.mobilisation_id + '.' + a + '.' + n; stickers.push({ area: a, n, code: s + '.' + sign(s) }); }
return { json: { project: item.json.project, stickers } };
